const $ = id => document.getElementById(id);
const stages = {
 url:{title:'It starts with a URL.',section:'THE STARTING POINT',icon:'↗',node:'browser',path:'',description:'You enter a web address. Your browser reads the protocol, hostname, and path — then needs an IP address to find its destination.',analogy:'Writing an address on an envelope. You know the name of the place, but first you need to find it on the map.',kind:'URL',code:'protocol  https:\nhost      www.example.com\npath      /hello',note:'This is a teaching simulation. No network request is sent.'},
 resolver:{title:'First, find the address.',section:'DNS LOOKUP',icon:'⌕',node:'resolver',path:'p-browser-resolver',description:'The browser and operating system check their DNS caches. On this first visit, neither has an answer, so a recursive DNS resolver is asked to look up the hostname.',analogy:'A librarian checks the index for you. If the answer is missing, they know which directories to consult.',kind:'DNS QUERY',code:'question  www.example.com\ntype      A (IPv4 address)\ncache     MISS',note:'A resolver may be run by your ISP or a DNS provider. Browsers can also use encrypted DNS. IPv6 uses AAAA records.'},
 root:{title:'Ask the root directory.',section:'DNS LOOKUP',icon:'◎',node:'root',path:'p-root',description:'With no cached referral, the resolver asks a root DNS server. It does not return the website’s IP address: it points the resolver to name servers for the .com top-level domain.',analogy:'The main directory tells the librarian which floor holds the .com section.',kind:'DNS REFERRAL',code:'resolver → root DNS\nquestion   www.example.com\nanswer     ask .com name servers',note:'The resolver makes the follow-up queries. Root servers do not forward your request along the chain.'},
 tld:{title:'Narrow it down to a domain.',section:'DNS LOOKUP',icon:'.',node:'tld',path:'p-tld',description:'The resolver asks a .com name server. This top-level domain (TLD) server refers it to the authoritative name servers responsible for example.com.',analogy:'The section index points to the exact shelf where the domain’s records live.',kind:'DNS REFERRAL',code:'resolver → .com DNS\nquestion   www.example.com\nanswer     authoritative servers',note:'Real resolvers often cache these referrals, so they do not need to start from the root every time.'},
 auth:{title:'A name becomes an IP.',section:'DNS LOOKUP',icon:'≡',node:'auth',path:'p-auth',description:'The authoritative DNS server answers from the domain’s records. The resolver caches the answer for its time to live (TTL) and returns the IP address to your browser.',analogy:'You finally get a street address. Keep a copy for a while so you do not need to look it up again.',kind:'DNS ANSWER · EXAMPLE',code:'www.example.com\nA       192.0.2.42\nTTL     300 seconds',note:'192.0.2.42 is a documentation address. Here it represents a CDN edge. Real DNS may involve CNAME aliases and multiple IPs.'},
 cached:{title:'The address is already here.',section:'DNS CACHE HIT',icon:'↺',node:'browser',path:'',description:'The browser already has an unexpired DNS answer for this hostname. It reuses the IP address, skipping the resolver, root, TLD, and authoritative lookups.',analogy:'You saved the address from your last visit. No need to call the directory again.',kind:'LOCAL DNS CACHE',code:'www.example.com → 192.0.2.42\nTTL remaining  184 seconds\nDNS lookup     SKIPPED',note:'This scenario assumes only DNS is cached. The browser still opens a new connection and fetches the page.'},
 connect:{title:'Make a connection.',section:'TCP CONNECTION',icon:'⇄',node:'cdn',path:'p-connect',description:'The browser connects to the CDN edge’s IP address on port 443. For this HTTP/2 example, a TCP handshake establishes a reliable, ordered connection.',analogy:'Dialing a number and hearing the other person pick up. Both sides confirm they can hear each other.',kind:'TCP · PORT 443',code:'browser → edge   SYN\nedge → browser   SYN-ACK\nbrowser → edge   ACK',note:'Not every site uses a CDN. HTTP/3 uses QUIC over UDP instead of this TCP handshake.'},
 tls:{title:'Secure the conversation.',section:'TLS HANDSHAKE',icon:'◇',node:'cdn',path:'p-connect',description:'TLS authenticates the server and establishes encryption keys. The browser checks that the certificate is trusted and valid for the hostname, then both sides can exchange encrypted data.',analogy:'Checking someone’s ID, then agreeing on a private way to talk that eavesdroppers cannot read.',kind:'TLS · SIMPLIFIED',code:'ClientHello → ServerHello\nverify certificate + hostname\nestablish encryption keys',note:'The diagram assumes TLS terminates at the CDN. The CDN uses a separate secure connection toward the origin.'},
 http:{title:'Ask for the page.',section:'HTTP REQUEST',icon:'→',node:'cdn',path:'p-connect',description:'Inside the encrypted connection, the browser sends an HTTP request for /hello. The CDN checks whether it has a fresh cached response; in this scenario, it needs the origin.',analogy:'Now that you have a private line, you can say exactly what you want to order.',kind:'HTTP/2 · READABLE VIEW',code:':method     GET\n:scheme     https\n:authority  www.example.com\n:path       /hello\nCDN cache   MISS',note:'HTTP/2 sends binary frames. This readable view shows request fields, not the exact bytes on the wire.'},
 lb:{title:'Choose a healthy server.',section:'REQUEST ROUTING',icon:'⑂',node:'lb',path:'p-forward',description:'The CDN forwards the request toward the origin. A load balancer selects a healthy application server and routes the request to it, helping distribute traffic across machines.',analogy:'A host at a busy restaurant sends you to an available table instead of making everyone wait at the same one.',kind:'UPSTREAM REQUEST',code:'CDN → load balancer\nhealth check  PASS\nselected      origin-02',note:'CDNs and load balancers are common, optional layers. A small website may use one server directly.'},
 server:{title:'Build the response.',section:'ORIGIN SERVER',icon:'▤',node:'server',path:'p-server',description:'The server routes /hello to the application. It may read a database, run logic, and generate HTML — or simply serve a static file. It returns a status, headers, and body.',analogy:'The kitchen prepares your order. A static file is ready on the shelf; a dynamic page is made when requested.',kind:'HTTP RESPONSE · READABLE VIEW',code:':status       200\ncontent-type  text/html\n\n<h1>Hello, world!</h1>',note:'Not every request uses a database. Some responses come from server caches, and applications can also return JSON or other data.'},
 edgehit:{title:'The edge has a copy.',section:'CDN CACHE HIT',icon:'ϟ',node:'cdn',path:'p-connect',description:'After DNS and HTTPS, the browser asks for /hello. The CDN finds a fresh, cacheable response and sends it straight back. The load balancer and origin do no work for this request.',analogy:'A neighborhood pickup point already has your order. There is no need to go all the way to the warehouse.',kind:'HTTP RESPONSE · CDN',code:':status       200\ncache-control public, max-age=300\nage           42\ncache         HIT',note:'This assumes a public, cacheable page. Personalized responses usually require different cache rules or must not be shared.'},
 render:{title:'The browser brings it to life.',section:'RESPONSE + RENDER',icon:'✦',node:'browser',path:'p-return',description:'The HTML comes back through the delivery layers. The browser parses it into a document, loads referenced CSS, JavaScript, and images, then lays out and paints the page.',analogy:'Your order arrives with assembly instructions. The browser puts the pieces together so you can see and use the result.',kind:'BROWSER PIPELINE',code:'HTML → DOM\nCSS  → styles\nlayout → paint → pixels\nJavaScript can update the page',note:'A page can start rendering before every resource arrives. Follow-up requests often reuse an existing connection.'},
 failed:{title:'No address. No connection.',section:'DNS ERROR',icon:'!',node:'auth',path:'p-answer',description:'In this simulated failure, the authoritative server returns NXDOMAIN: this hostname does not exist. Without an IP address, the browser cannot begin its connection to the website.',analogy:'The directory says there is no such address. Your envelope cannot be delivered until the name is corrected.',kind:'DNS RESPONSE',code:'question  typo.example.com\nstatus    NXDOMAIN\nHTTP      not reached',note:'This differs from HTTP 404: a 404 means you reached a server, but it could not find the requested resource.'}
};
const routes={cold:['url','resolver','root','tld','auth','connect','tls','http','lb','server','render'],warm:['url','cached','connect','tls','http','lb','server','render'],edge:['url','resolver','root','tld','auth','connect','tls','edgehit','render'],failure:['url','resolver','root','tld','failed']};
let scenario='cold',index=0,playing=false,stepMotion=false,timer=null,speed=1;
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
const route=()=>routes[scenario];
function schedule(){clearTimeout(timer);if(playing)timer=setTimeout(()=>{if(index<route().length-1){index++;render();schedule();}else{playing=false;render();}},6000/speed);}
function setPlaying(value){stepMotion=false;playing=value;render();schedule();}
function goTo(value){stepMotion=true;index=Math.max(0,Math.min(value,route().length-1));playing=false;clearTimeout(timer);render();}
function setScenario(value){if(!Object.hasOwn(routes,value))throw new Error('Unknown scenario');scenario=value;stepMotion=false;$('scenario').value=value;index=0;playing=false;clearTimeout(timer);render();}
function render(){
 const key=route()[index],s=stages[key];
 $('stage-label').textContent=String(index+1).padStart(2,'0')+' — '+s.section;
 $('step-count').textContent=`${index+1} / ${route().length}`;
 $('step-icon').textContent=s.icon;$('step-title').textContent=s.title;
 $('step-description').textContent=s.description;$('analogy').textContent=s.analogy;
 $('code-kind').textContent=s.kind;$('packet-code').textContent=s.code;
 $('detail-note').textContent=s.note;
 document.querySelector('.address strong').textContent=scenario==='failure'?'typo.example.com':'www.example.com';
 if(scenario==='failure')$('packet-code').textContent=s.code.replaceAll('www.example.com','typo.example.com');
 if(key==='render'&&scenario==='edge'){$('step-description').textContent='The cached HTML comes straight back from the CDN. The browser parses it, fetches referenced resources, and turns it into the page you see. The origin was skipped for this request.';}
 document.querySelectorAll('.node').forEach(n=>{n.classList.toggle('active',n.dataset.node===s.node);n.setAttribute('aria-pressed',String(n.dataset.node===s.node));});
 let path=s.path?$(s.path).getAttribute('d'):'';
 if(key==='auth')path+=' M443 220H365V115H326 M234 115H123V310';
 if(key==='render'&&scenario==='edge')path='M273 350H170';
 $('travel').setAttribute('d',path);$('packet').style.display=path&&!reducedMotion?'':'none';
 $('packet-motion').setAttribute('path',path||'M0 0');$('packet-motion').setAttribute('dur',`${2/speed}s`);
 if($('packet-motion').beginElement)$('packet-motion').beginElement();
 const svg=document.querySelector('.connections');
 const animateConnection=(playing||stepMotion)&&!reducedMotion;
 document.body.classList.toggle('paused',!animateConnection);
 if(animateConnection)svg.unpauseAnimations();else svg.pauseAnimations();
 $('play').innerHTML=playing?'Ⅱ <span>Pause</span>':index===route().length-1?'↺ <span>Replay</span>':'▶ <span>Play journey</span>';
 $('play').setAttribute('aria-label',playing?'Pause animation':'Play animation');
 $('back').disabled=index===0;$('next').disabled=index===route().length-1;
 $('timeline').replaceChildren(...route().map((k,i)=>{const b=document.createElement('button');b.className=i===index?'current':i<index?'visited':'';b.setAttribute('aria-label',`Step ${i+1}: ${stages[k].title}`);b.setAttribute('aria-current',i===index?'step':'false');b.title=stages[k].title;b.addEventListener('click',()=>goTo(i));return b;}));
}
$('play').addEventListener('click',()=>{if(!playing&&index===route().length-1)index=0;setPlaying(!playing);});
$('send').addEventListener('click',()=>{index=0;setPlaying(true);});
$('back').addEventListener('click',()=>goTo(index-1));$('next').addEventListener('click',()=>goTo(index+1));$('reset').addEventListener('click',()=>goTo(0));
$('scenario').addEventListener('change',e=>setScenario(e.target.value));
$('speed').addEventListener('change',e=>{speed=Number(e.target.value);render();schedule();});
document.querySelectorAll('.node').forEach(n=>n.addEventListener('click',()=>{let i=route().findIndex(k=>stages[k].node===n.dataset.node);if(i<0){setScenario('cold');i=route().findIndex(k=>stages[k].node===n.dataset.node);}goTo(i);}));
const quizzes=[
 {q:'What does DNS give your browser?',a:['An IP address','The HTML page','A password'],correct:0,explain:'DNS resolves a hostname to an IP address. HTTP is used to request the page after a connection is established.'},
 {q:'What changes when the CDN has a fresh cached page?',a:['DNS is unnecessary','The origin can be skipped','TLS is disabled'],correct:1,explain:'The edge can answer directly. The browser still needs an address and a secure connection to the CDN.'},
 {q:'How is NXDOMAIN different from HTTP 404?',a:['They are identical','404 means DNS failed','404 comes from a server'],correct:2,explain:'NXDOMAIN means the hostname does not exist. A 404 means a server was reached but the requested resource was not found.'}
];let quizIndex=0,answered=false;
function showQuiz(){const q=quizzes[quizIndex];answered=false;$('quiz-question').textContent=q.q;$('quiz-count').textContent=`0${quizIndex+1} / 03`;$('quiz-feedback').textContent='';$('quiz-next').hidden=true;$('quiz-answers').replaceChildren(...q.a.map((a,i)=>{const b=document.createElement('button');b.textContent=a;b.addEventListener('click',()=>{if(answered)return;answered=true;const buttons=$('quiz-answers').children;buttons[q.correct].classList.add('correct');if(i!==q.correct)b.classList.add('incorrect');$('quiz-feedback').textContent=(i===q.correct?'Correct. ':'Not quite. ')+q.explain;$('quiz-next').hidden=false;$('quiz-next').textContent=quizIndex===2?'Try the questions again ↺':'Next question →';});return b;}));}
$('quiz-next').addEventListener('click',()=>{quizIndex=(quizIndex+1)%quizzes.length;showQuiz();});
render();showQuiz();
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const tool={name:'explore_web_request',title:'Explore a web request',description:'Select a teaching scenario and navigate to a step in the visible request journey. This only changes the simulation; it sends no network request.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:Object.keys(routes)},step:{type:'integer',minimum:1}},required:['scenario','step'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Object.hasOwn(routes,input.scenario)||!Number.isInteger(input.step)||input.step<1||input.step>routes[input.scenario].length)throw new Error('Choose a valid scenario and a step within its journey.');setScenario(input.scenario);goTo(input.step-1);return {scenario,step:index+1,totalSteps:route().length,title:stages[route()[index]].title};}};
 try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
